def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    net_change = v2 - v1

    return {
        "value": net_change,
        "trace": {
            "starting_liability": v1,
            "ending_liability": v2,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
